"use client";
import { Button } from "@mui/material";
import {
    openDeletePubPopup,
    openQrCodePopup,
    openUpdatePubPopup,
} from "../pub/pubSlice";
import { useDispatch } from "react-redux";
import { NavLink, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { ConvertQrMenuApiTimeToLocal } from "@/utils/time";
import { openPayForPubPopup } from "./companySlice";

const CompanyPub = ({ pub }) => {
    const { t, i18n } = useTranslation();
    const dispatch = useDispatch();
    const navigate = useNavigate();

    const handleEditClick = () => {
        dispatch(openUpdatePubPopup(pub));
    };

    const handleDeleteClick = () => {
        dispatch(
            openDeletePubPopup({ companyID: pub.company_id, pubID: pub.id })
        );
    };

    const pubURL = `https://qrmenu.sandex.md/pub/${pub.url_name}/`

    const handleOpenQrCode = () => {
        dispatch(openQrCodePopup({ imageFileName: pub.qr_code_file_name, pubURL: pubURL }));
    };

    const goToPub = () => {
        navigate(`/admin/pub/${pub.id}`);
    };

    const handlePayButtonClick = () => {
        dispatch(openPayForPubPopup())
    }

    return (
        <div
            style={{
                width: "100%",
                maxWidth: "200px",
                transition: "all .2s ease-in-out",
            }}
            className="cursor-pointer border p-6 rounded-lg shadow-xl hover:shadow-2xl flex flex-col justify-between"
        >
            <header className="flex justify-between">
                <div className="cursor-pointer">
                    <img
                        onClick={handleOpenQrCode}
                        src="/static/admin/images/svg/qr-code-black.svg"
                        alt="qr-code"
                        width={25}
                        height={25}
                    />
                </div>
            </header>
            <main className="block mb-2">
                <div className="mb-4 text-2xs text-gray-700">
                    {t("admin.company.pub.expiration_time")}
                    <br />
                    <span>
                        {ConvertQrMenuApiTimeToLocal(
                            pub.expiration_time_utc,
                            i18n.language
                        )}
                    </span>
                </div>
                <div className="mb text-base font-bold">{pub.name}</div>
                <div className="mb text-xs text-gray-700 break-words">
                    {t("admin.company.pub.address")}: {pub.address}
                </div>
                {pub.expired && (
                    <div className=" text-red-600 uppercase text-center py px-4 border border-red-600 mt-3 rounded-lg">
                        {t("admin.company.pub.expired")}
                    </div>
                )}
            </main>
            <footer
                className="flex flex-col text-center"
                style={
                    pub.expired
                        ? { mt: "4px", alignItems: "center" }
                        : { mt: "24px", alignItems: "left" }
                }
            >
                <Button
                    variant="contained"
                    sx={{
                        color: "white",
                        bgcolor: "rgb(31 41 55)",
                        fontSize: ".5rem",
                        fontWeight: "medium",
                        padding: ".4rem .5rem",
                        borderRadius: "20px",
                        textAlign: "left",
                        width: "90%",
                        ":hover": {
                            bgcolor: "rgb(17 24 39)",
                        },
                    }}
                    onClick={pub.expired ? handlePayButtonClick : goToPub}
                >
                    {pub.expired ? t("admin.company.pub.pay_button") : t("admin.company.pub.edit_button")}
                </Button>
            </footer>
        </div>
    );
};

export default CompanyPub;
